"use client"

import { useState, useEffect } from "react"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import { FileText, Loader2, Calendar } from "lucide-react"
import { fetchGlobalCashBook, type GlobalCashBook } from "@/lib/api"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover"
import { Calendar as CalendarComponent } from "@/components/ui/calendar"
import { format, subDays } from "date-fns"

function formatCurrency(amount: number): string {
  return `RWF ${amount.toLocaleString()}`
}

function StatementRow({
  label,
  amount,
  variant = "normal",
  isNegative = false,
}: {
  label: string
  amount?: number | string
  variant?: "normal" | "indent" | "indent-2" | "total" | "grand-total" | "highlight"
  isNegative?: boolean
}) {
  const baseStyles = "flex justify-between py-3 px-4 border-b border-border"
  const variantStyles = {
    normal: "",
    indent: "pl-10",
    "indent-2": "pl-16 text-muted-foreground",
    total: "font-semibold bg-secondary border-t-2 border-b-2 border-border mt-2",
    "grand-total": "bg-primary text-primary-foreground font-semibold text-lg mt-4",
    highlight: "bg-secondary mt-4",
  }

  const formatAmount = (amt: number | string | undefined) => {
    if (amt === undefined || amt === null) return ""
    const numAmount = typeof amt === "string" ? parseFloat(amt) : amt
    return formatCurrency(numAmount)
  }

  return (
    <div className={`${baseStyles} ${variantStyles[variant]}`}>
      <span>{label}</span>
      {amount !== undefined && (
        <span
          className={`font-serif font-semibold tabular-nums ${
            isNegative ? "text-red-600 dark:text-red-400" : ""
          }`}
        >
          {formatAmount(amount)}
        </span>
      )}
    </div>
  )
}

export function GlobalCashBook() {
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [data, setData] = useState<any | null>(null)
  const [startDate, setStartDate] = useState<Date>(subDays(new Date(), 30))
  const [endDate, setEndDate] = useState<Date>(new Date())
  const [isStartCalendarOpen, setIsStartCalendarOpen] = useState(false)
  const [isEndCalendarOpen, setIsEndCalendarOpen] = useState(false)

  useEffect(() => {
    async function loadData() {
      try {
        setLoading(true)
        setError(null)
        const startDateString = format(startDate, "yyyy-MM-dd")
        const endDateString = format(endDate, "yyyy-MM-dd")
        const response = await fetchGlobalCashBook(startDateString, endDateString)
        console.log("Global Cash Book:", response)
        setData(response)
      } catch (err) {
        setError(err instanceof Error ? err.message : "Failed to load cash book")
      } finally {
        setLoading(false)
      }
    }
    loadData()
  }, [startDate, endDate])

  const handleExportPDF = () => {
    // TODO: Implement PDF export
    console.log("Export PDF clicked")
  }

  if (loading) {
    return (
      <Card>
        <CardContent className="flex items-center justify-center min-h-[400px]">
          <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
        </CardContent>
      </Card>
    )
  }

  if (error) {
    return (
      <Card>
        <CardContent className="flex items-center justify-center min-h-[400px]">
          <div className="text-center">
            <p className="text-sm text-destructive">{error}</p>
            <p className="text-xs text-muted-foreground mt-2">
              Please try again or contact support
            </p>
          </div>
        </CardContent>
      </Card>
    )
  }

  if (!data || !data.summary || !data.companies) {
    return (
      <Card>
        <CardContent className="flex items-center justify-center min-h-[400px]">
          <div className="text-center">
            <p className="text-sm text-muted-foreground">No cash book data available</p>
          </div>
        </CardContent>
      </Card>
    )
  }

  const { summary, companies } = data

  return (
    <div className="space-y-6">
      <Card>
        <CardHeader className="flex flex-row items-center justify-between">
          <div>
            <CardTitle className="font-serif">Global Cash Book</CardTitle>
            <p className="text-sm text-muted-foreground mt-1 italic">
              {format(startDate, "dd MMM yyyy")} - {format(endDate, "dd MMM yyyy")}
            </p>
            <p className="text-xs text-muted-foreground mt-1">
              {companies.length} {companies.length === 1 ? "Company" : "Companies"}
            </p>
          </div>
          <div className="flex gap-2">
            <div className="flex gap-2 items-center">
              <Popover open={isStartCalendarOpen} onOpenChange={setIsStartCalendarOpen}>
                <PopoverTrigger asChild>
                  <Button variant="outline" size="sm">
                    <Calendar className="h-4 w-4 mr-2" />
                    From: {format(startDate, "dd MMM yyyy")}
                  </Button>
                </PopoverTrigger>
                <PopoverContent className="w-auto p-0" align="end">
                  <CalendarComponent
                    mode="single"
                    selected={startDate}
                    onSelect={(date) => {
                      if (date) {
                        setStartDate(date)
                        setIsStartCalendarOpen(false)
                      }
                    }}
                    disabled={(date) => date > endDate}
                    initialFocus
                  />
                </PopoverContent>
              </Popover>

              <Popover open={isEndCalendarOpen} onOpenChange={setIsEndCalendarOpen}>
                <PopoverTrigger asChild>
                  <Button variant="outline" size="sm">
                    <Calendar className="h-4 w-4 mr-2" />
                    To: {format(endDate, "dd MMM yyyy")}
                  </Button>
                </PopoverTrigger>
                <PopoverContent className="w-auto p-0" align="end">
                  <CalendarComponent
                    mode="single"
                    selected={endDate}
                    onSelect={(date) => {
                      if (date) {
                        setEndDate(date)
                        setIsEndCalendarOpen(false)
                      }
                    }}
                    disabled={(date) => date > new Date() || date < startDate}
                    initialFocus
                  />
                </PopoverContent>
              </Popover>
            </div>

            <Button
              onClick={handleExportPDF}
              className="bg-accent text-accent-foreground hover:bg-accent/90"
            >
              <FileText className="h-4 w-4 mr-2" />
              Export PDF
            </Button>
          </div>
        </CardHeader>
        <CardContent>
          <div className="space-y-6">
            {/* Summary Statistics */}
            <div className="grid grid-cols-3 gap-4 p-4 bg-muted/50 rounded-lg">
              <div className="text-center">
                <p className="text-xs text-muted-foreground mb-1">Total Cash In</p>
                <p className="text-lg font-bold font-mono tabular-nums text-green-600 dark:text-green-400">
                  {formatCurrency(summary.totalCashIn)}
                </p>
              </div>
              <div className="text-center">
                <p className="text-xs text-muted-foreground mb-1">Total Cash Out</p>
                <p className="text-lg font-bold font-mono tabular-nums text-red-600 dark:text-red-400">
                  {formatCurrency(summary.totalCashOut)}
                </p>
              </div>
              <div className="text-center">
                <p className="text-xs text-muted-foreground mb-1">Net Cash Flow</p>
                <p className={`text-lg font-bold font-mono tabular-nums ${
                  summary.netCashFlow >= 0 
                    ? 'text-green-600 dark:text-green-400' 
                    : 'text-red-600 dark:text-red-400'
                }`}>
                  {summary.netCashFlow >= 0 ? '+' : ''}{formatCurrency(summary.netCashFlow)}
                </p>
              </div>
            </div>

            {/* Cash Flow Summary */}
            <div>
              <h3 className="text-lg font-serif font-semibold text-primary border-b-2 border-primary pb-2 mb-4">
                Consolidated Cash Flow Summary
              </h3>
              <StatementRow
                label="Total Cash Inflows"
                amount={summary.totalCashIn}
                variant="indent"
              />
              <StatementRow
                label="Total Cash Outflows"
                amount={summary.totalCashOut}
                variant="indent"
                isNegative
              />
              <StatementRow
                label="Net Cash Flow"
                amount={summary.netCashFlow}
                variant="grand-total"
                isNegative={summary.netCashFlow < 0}
              />
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Company Breakdown */}
      <Card>
        <CardHeader>
          <CardTitle className="font-serif text-base">Cash Flow by Company</CardTitle>
        </CardHeader>
        <CardContent>
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Company</TableHead>
                <TableHead className="text-right">Cash In</TableHead>
                <TableHead className="text-right">Cash Out</TableHead>
                <TableHead className="text-right">Net Cash Flow</TableHead>
                <TableHead className="text-right">Transactions</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {companies.map((company: any, index: number) => (
                <TableRow key={index}>
                  <TableCell className="font-medium">{company.companyName}</TableCell>
                  <TableCell className="text-right font-mono tabular-nums text-green-600 dark:text-green-400">
                    {formatCurrency(company.totalCashIn)}
                  </TableCell>
                  <TableCell className="text-right font-mono tabular-nums text-red-600 dark:text-red-400">
                    {formatCurrency(company.totalCashOut)}
                  </TableCell>
                  <TableCell
                    className={`text-right font-mono tabular-nums font-semibold ${
                      company.netCashFlow >= 0
                        ? "text-green-600 dark:text-green-400"
                        : "text-red-600 dark:text-red-400"
                    }`}
                  >
                    {company.netCashFlow >= 0 ? "+" : ""}
                    {formatCurrency(company.netCashFlow)}
                  </TableCell>
                  <TableCell className="text-right font-mono tabular-nums">
                    {company.transactionCount}
                  </TableCell>
                </TableRow>
              ))}
              <TableRow className="bg-secondary font-semibold border-t-2">
                <TableCell>Total</TableCell>
                <TableCell className="text-right font-mono tabular-nums text-green-600 dark:text-green-400">
                  {formatCurrency(summary.totalCashIn)}
                </TableCell>
                <TableCell className="text-right font-mono tabular-nums text-red-600 dark:text-red-400">
                  {formatCurrency(summary.totalCashOut)}
                </TableCell>
                <TableCell
                  className={`text-right font-mono tabular-nums ${
                    summary.netCashFlow >= 0
                      ? "text-green-600 dark:text-green-400"
                      : "text-red-600 dark:text-red-400"
                  }`}
                >
                  {summary.netCashFlow >= 0 ? "+" : ""}
                  {formatCurrency(summary.netCashFlow)}
                </TableCell>
                <TableCell className="text-right font-mono tabular-nums">
                  {companies.reduce((sum: number, c: any) => sum + c.transactionCount, 0)}
                </TableCell>
              </TableRow>
            </TableBody>
          </Table>
        </CardContent>
      </Card>

      {/* Cash Flow Analysis */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <Card>
          <CardHeader>
            <CardTitle className="font-serif text-base">Cash Flow Breakdown</CardTitle>
          </CardHeader>
          <CardContent>
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Company</TableHead>
                  <TableHead className="text-right">Net Cash Flow</TableHead>
                  <TableHead className="text-right">% of Total</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {companies.map((company: any, index: number) => {
                  const totalAbsoluteFlow = companies.reduce(
                    (sum: number, c: any) => sum + Math.abs(c.netCashFlow),
                    0
                  )
                  const percentage =
                    totalAbsoluteFlow > 0
                      ? ((Math.abs(company.netCashFlow) / totalAbsoluteFlow) * 100).toFixed(1)
                      : "0.0"
                  return (
                    <TableRow key={index}>
                      <TableCell>{company.companyName}</TableCell>
                      <TableCell
                        className={`text-right font-mono tabular-nums font-semibold ${
                          company.netCashFlow >= 0
                            ? "text-green-600 dark:text-green-400"
                            : "text-red-600 dark:text-red-400"
                        }`}
                      >
                        {company.netCashFlow >= 0 ? "+" : ""}
                        {formatCurrency(company.netCashFlow)}
                      </TableCell>
                      <TableCell className="text-right tabular-nums font-semibold">
                        {percentage}%
                      </TableCell>
                    </TableRow>
                  )
                })}
              </TableBody>
            </Table>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle className="font-serif text-base">Activity Overview</CardTitle>
          </CardHeader>
          <CardContent>
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Company</TableHead>
                  <TableHead className="text-right">Transactions</TableHead>
                  <TableHead className="text-right">Avg per Transaction</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {companies
                  .sort((a: any, b: any) => b.transactionCount - a.transactionCount)
                  .map((company: any, index: number) => {
                    const avgTransaction =
                      company.transactionCount > 0
                        ? (company.totalCashIn + company.totalCashOut) / company.transactionCount
                        : 0
                    return (
                      <TableRow key={index}>
                        <TableCell>{company.companyName}</TableCell>
                        <TableCell className="text-right font-mono tabular-nums">
                          {company.transactionCount}
                        </TableCell>
                        <TableCell className="text-right font-mono tabular-nums">
                          {formatCurrency(avgTransaction)}
                        </TableCell>
                      </TableRow>
                    )
                  })}
              </TableBody>
            </Table>
          </CardContent>
        </Card>
      </div>
    </div>
  )
}